commands.run:
gh pr diff "$PR_NUMBER" --repo "$REPO" | awk '
  /^diff --git/ { print; next }
  /^index / { print; next }
  /^---/ { print; next }
  /^\+\+\+/ { print; next }
  /^Binary files / { print; next }
  /^@@/ {
    split($2, old_parts, ",")
    split($3, new_parts, ",")
    old_line = -old_parts[1]
    new_line = substr(new_parts[1], 2)
    print
    next
  }
  /^-/ { printf "[OLD:%d]%s\n", old_line++, $0; next }
  /^\+/ { printf "[NEW:%d]%s\n", new_line++, $0; next }
  { printf "[OLD:%d,NEW:%d]%s\n", old_line++, new_line++, $0 }
' | head -10000 > pr_diff.txt

gh api graphql -f query='
  mutation ($labelableId: ID!, $labelIds: [ID!]!) {
    addLabelsToLabelable(
      input: {labelableId: $labelableId, labelIds: $labelIds}
    ) {
        clientMutationId
    }
  }' -f labelableId="$ITEM_ID" -f labelIds="$LABEL_IDS"

gh api graphql -f query='
  query($org: String!, $repo: String!, $issueNumber: Int!) {
    repository(name: $repo, owner: $org) {
      issue (number: $issueNumber) {
        id
        projectItems(first:20) {
          nodes {
            project {
              number,
            },
          }
        }
      }
    }
  }' -f org="$ORGANIZATION" -f repo="$REPO" -F issueNumber="$ISSUE_NUMBER" > projects_data.json
